import React from 'react';

import { getHikingSchedule } from '@apps/Hiking/@services/hikingSchedule.service';
import { IHikingScheduleItem } from '@apps/Hiking/@types/hiking.baseTypes';
import ScheduleItem from '@apps/Hiking/schedule/components/ScheduleItem';
import PageLoader from '@components/PageLoader';
import PohAlert, { AlertVariant } from '@ui-kit/Alert';
import Empty from '@ui-kit/Empty';
import PohInput, { InputTypes } from '@ui-kit/Input';
import PohList from '@ui-kit/List';
import { showModal } from '@ui-kit/Modal';

interface IHikingScheduleItemsListProps {
  id_hiking: number;
  onSelectItem: (item: IHikingScheduleItem) => void;
}
const HikingScheduleItemsList: React.FC<IHikingScheduleItemsListProps> = ({
  id_hiking,
  onSelectItem,
}) => {
  const [isLoading, setIsLoading] = React.useState(true);
  const [err, setErr] = React.useState<Error>();
  const [data, setData] = React.useState<IHikingScheduleItem[]>([]);
  const [q, setQ] = React.useState('');

  const load = React.useCallback(async () => {
    try {
      setIsLoading(true);
      const res = await getHikingSchedule(id_hiking);
      setData(res);
    } catch (e) {
      setErr(e as Error);
    } finally {
      setIsLoading(false);
    }
  }, [id_hiking]);

  React.useEffect(() => {
    load();
  }, [load]);

  const filteredData = React.useMemo(() => {
    if (!q.length) return data;
    return data.filter((x) => x.name.toLocaleLowerCase().includes(q.toLowerCase()));
  }, [data, q]);

  if (isLoading) return <PageLoader />;
  if (err) return <PohAlert variant={AlertVariant.Danger}>{err.message}</PohAlert>;

  return (
    <div>
      {data.length > 0 && (
        <>
          <PohInput type={InputTypes.search} value={q} onChange={setQ} placeholder="Найти" />
        </>
      )}
      {filteredData.length === 0 && <Empty>Пусто...</Empty>}
      {filteredData.length > 0 && (
        <div style={{ maxHeight: 480, overflowY: 'auto' }}>
          <PohList
            flush
            data={filteredData.map((item) => {
              return {
                key: item.id,
                className: 'p-0',
                children: <ScheduleItem scheduleItem={item} id_hiking={id_hiking} />,
                action: true,
                onClick: (e) => {
                  e.stopPropagation();
                  onSelectItem(item);
                },
              };
            })}
          />
        </div>
      )}
    </div>
  );
};

export const selectHikingScheduleItemInModal = (
  id_hiking: number,
): Promise<IHikingScheduleItem> => {
  return new Promise((res) => {
    showModal({
      style: { minWidth: 400 },
      children: (clos) => (
        <HikingScheduleItemsList
          id_hiking={id_hiking}
          onSelectItem={(r) => {
            res(r);
            clos();
          }}
        />
      ),
    });
  });
};
